      <div class="ctrl-head"><label for="quad-demo-b">b</label><output data-viz-out="b">b = 0</output></div>
      <input id="quad-demo-b" name="b" type="range" min="-8" max="8" step="0.1" value="0">
    </div>
    <div class="control">
      <div class="ctrl-head"><label for="quad-demo-c">c</label><output data-viz-out="c">c = 0</output></div>
      <input id="quad-demo-c" name="c" type="range" min="-8" max="8" step="0.1" value="0">
    </div>
  </div>
</div>
<script>
(function () {
  var root = document.getElementById('quad-demo');
  if (!root) return;
  var NS = 'http://www.w3.org/2000/svg';
  var plot = root.querySelector('.plot');
  var svg = root.querySelector('svg');
  var out = function (key) { return root.querySelector('[data-viz-out="' + key + '"]'); };

  var entered = false;          // entrance animation plays once
  var last = null;              // last params + window, for resize redraws
  var lastW = 0, lastH = 0;
  var reduced = false;
  try { reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (e) { reduced = false; }

  function el(name, attrs, text) {
    var node = document.createElementNS(NS, name);
    if (attrs) for (var k in attrs) if (Object.prototype.hasOwnProperty.call(attrs, k) && attrs[k] !== null && attrs[k] !== undefined) node.setAttribute(k, attrs[k]);
    if (text !== undefined) node.textContent = text;
    return node;
  }
  function round(n, d) { var m = Math.pow(10, d === undefined ? 1 : d); var v = Math.round(n * m) / m; return v === 0 ? 0 : v; }
  function fmt(n, d) {
    var v = round(n, d === undefined ? 1 : d);
    if (!isFinite(v)) return '—';
    if (Math.abs(v - Math.round(v)) < 1e-9) return String(Math.round(v));
    return v.toFixed(d === undefined ? 1 : d);
  }
  function niceStep(span, target) {
    var raw = span / target, mag = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), norm = raw / mag;
    return (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 5 ? 5 : 10) * mag;
  }
  function readNum(raw, d) {
    var n = raw === undefined || raw === null || raw === '' ? NaN : Number(raw);
    return isFinite(n) ? n : d;
  }
  function equation(a, b, c) {
    var out = 'y = ';
    if (Math.abs(a) < 1e-6) {
      if (Math.abs(b) < 1e-6) return out + fmt(c);
      out += b === 1 ? 'x' : b === -1 ? '−x' : fmt(b) + 'x';
      return c === 0 ? out : out + (c > 0 ? ' + ' : ' − ') + fmt(Math.abs(c));
    }
    out += (a === 1 ? '' : a === -1 ? '−' : fmt(a)) + 'x²';
    if (b !== 0) out += (b > 0 ? ' + ' : ' − ') + (Math.abs(b) === 1 ? '' : fmt(Math.abs(b))) + 'x';
    if (c !== 0) out += (c > 0 ? ' + ' : ' − ') + fmt(Math.abs(c));
    return out;
  }

  // --- window: the parabola chooses its own view, with hysteresis -----------
  function targetWindow(a, b, c) {
    if (Math.abs(a) < 1e-6) {
      var hw = 4, lo = Math.min(b * -hw + c, b * hw + c), hi = Math.max(b * -hw + c, b * hw + c);
      var p = Math.max(0.8, (hi - lo) * 0.15);
      return { xmin: -hw, xmax: hw, ymin: lo - p, ymax: hi + p };
    }
    var h = -b / (2 * a), k = c - b * b / (4 * a), up = a > 0;
    var spanY = Math.max(Math.abs(k) * 2.5, 1.8);
    var s = spanY / 0.4;                       // vertex at 25% from its edge
    var limit = Math.max(Math.abs(k) * 1.85, 0.75);
    if (up) { if (Math.max(0, k) + 0.75 * s < limit) s = (limit - Math.max(0, k)) / 0.75; }
    else { if (k - 0.75 * s > -limit) s = (k + limit) / 0.75; }
    var ymin, ymax;
    if (up) { ymin = k - 0.25 * s; ymax = k + 0.75 * s; }
    else { ymax = k + 0.25 * s; ymin = k - 0.75 * s; }
    var vf = up ? 0.25 : 0.75;                 // vertex fraction from the bottom
    var top = up ? ymax : ymin;                // the edge the branches run to
    var half = Math.sqrt(Math.abs((top - k) / a)) / 0.85;
    half = Math.max(half, up ? 2.2 : 2.2);
    var pad = half * 0.06;
    return { xmin: h - half - pad, xmax: h + half + pad, ymin: ymin, ymax: ymax, vf: vf };
  }
  function holds(w, a, b, c) {
    var h = -b / (2 * a), k = c - b * b / (4 * a), up = a > 0;
    var spanY = w.ymax - w.ymin, spanX = w.xmax - w.xmin;
    var xPad = spanX * 0.08, yPad = spanY * 0.08;
    if (h < w.xmin + xPad || h > w.xmax - xPad) return false;
    if (k < w.ymin + yPad || k > w.ymax - yPad) return false;
    var edge = up ? w.ymax - yPad : w.ymin + yPad;
    var xe = Math.sqrt(Math.abs((edge - k) / a));
    if (!(h - xe >= w.xmin + xPad && h + xe <= w.xmax - xPad)) return false;
    var ideal = targetWindow(a, b, c);
    var rx = spanX / (ideal.xmax - ideal.xmin);
    var ry = spanY / (ideal.ymax - ideal.ymin);
    if (rx > 1.4 || rx < 0.75 || ry > 1.4 || ry < 0.75) return false;
    var vf = (k - w.ymin) / spanY;
    if (a > 0 ? (vf < 0.10 || vf > 0.40) : (vf < 0.60 || vf > 0.90)) return false;
    return true;
  }
  function chooseWindow(a, b, c, prev) {
    if (prev && Math.abs(a) > 1e-6 && holds(prev, a, b, c)) return prev;
    return targetWindow(a, b, c);
  }

  // --- draw ---------------------------------------------------------------
  function draw(params, animate) {
    var a = params.a, b = params.b, c = params.c;
    var w = Math.max(1, Math.round(plot.clientWidth || 0));
    var hpx = Math.max(1, Math.round(plot.clientHeight || 0));
    lastW = w; lastH = hpx;
    svg.setAttribute('width', String(w));
    svg.setAttribute('height', String(hpx));
    svg.setAttribute('viewBox', '0 0 ' + w + ' ' + hpx);
    while (svg.firstChild) svg.removeChild(svg.firstChild);

    var win = chooseWindow(a, b, c, last ? last.win : null);
    var padL = 46, padR = 22, padT = 16, padB = 28;
    var iw = Math.max(30, w - padL - padR), ih = Math.max(30, hpx - padT - padB);
    var sx = function (x) { return padL + (x - win.xmin) / (win.xmax - win.xmin) * iw; };
    var sy = function (y) { return padT + (win.ymax - y) / (win.ymax - win.ymin) * ih; };

    var defs = el('defs');
    var clip = el('clipPath', { id: 'quad-demo-clip' });
    clip.appendChild(el('rect', { x: padL, y: padT, width: iw, height: ih }));
    defs.appendChild(clip);
    var grad = el('linearGradient', { id: 'quad-demo-grad', x1: 0, y1: 0, x2: 0, y2: 1 });
    grad.appendChild(el('stop', { offset: '0%', 'stop-color': 'var(--viz-series-1)', 'stop-opacity': '0.20' }));
    grad.appendChild(el('stop', { offset: '100%', 'stop-color': 'var(--viz-series-1)', 'stop-opacity': '0.02' }));
    defs.appendChild(grad);
    svg.appendChild(defs);

    var xStep = niceStep(win.xmax - win.xmin, 9), yStep = niceStep(win.ymax - win.ymin, 7);
    var xTicks = [], yTicks = [], i;
    for (i = Math.ceil(win.xmin / xStep) * xStep; i <= win.xmax + 1e-9; i += xStep) xTicks.push(round(i, 6));
    for (i = Math.ceil(win.ymin / yStep) * yStep; i <= win.ymax + 1e-9; i += yStep) yTicks.push(round(i, 6));

    var g = el('g');
    xTicks.forEach(function (tx) { g.appendChild(el('line', { x1: sx(tx), y1: padT, x2: sx(tx), y2: padT + ih, class: 'grid-line' })); });
    yTicks.forEach(function (ty) { g.appendChild(el('line', { x1: padL, y1: sy(ty), x2: padL + iw, y2: sy(ty), class: 'grid-line' })); });

    var xVisible = win.ymin <= 0 && 0 <= win.ymax;
    var yVisible = win.xmin <= 0 && 0 <= win.xmax;
    var xAxisY = sy(0), yAxisX = sx(0);
    var xAxisG = el('g'), yAxisG = el('g');
    if (xVisible) {
      xAxisG.appendChild(el('line', { x1: padL, y1: xAxisY, x2: padL + iw, y2: xAxisY, class: 'axis-line' }));
      xAxisG.appendChild(el('path', { d: 'M' + (padL + iw) + ',' + xAxisY + ' l-7,-3.5 v7 z', fill: 'var(--viz-axis)' }));
    }
    if (yVisible) {
      yAxisG.appendChild(el('line', { x1: yAxisX, y1: padT, x2: yAxisX, y2: padT + ih, class: 'axis-line' }));
      yAxisG.appendChild(el('path', { d: 'M' + yAxisX + ',' + padT + ' l-3.5,7 h7 z', fill: 'var(--viz-axis)' }));
    }
    // x/y direction letters at the positive ends — required on every plot
    xAxisG.appendChild(el('text', { class: 'axis-label axis-label-x', x: padL + iw, y: xAxisY - 10 }, 'x'));
    yAxisG.appendChild(el('text', { class: 'axis-label axis-label-y', x: yAxisX + 10, y: padT + 14 }, 'y'));
    svg.appendChild(g);
    svg.appendChild(xAxisG);
    svg.appendChild(yAxisG);

    // tick numbers: 11px in the foreground colour, collisions dropped not overlapped
    var placed = [];
    function widthOf(label) { return label.length * 6.2; }
    function collides(x0, x1, y0, y1) {
      for (var j = 0; j < placed.length; j++) {
        var r = placed[j];
        if (x0 < r.x1 && x1 > r.x0 && y0 < r.y1 && y1 > r.y0) return true;
      }
      return false;
    }
    function addLabel(label, x, y, anchor) {
      var wpx = widthOf(label);
      var x0 = anchor === 'end' ? x - wpx : anchor === 'middle' ? x - wpx / 2 : x;
      var x1 = x0 + wpx;
      if (x1 > padL + iw - 26) return;     // keep clear of the x axis letter
      if (collides(x0, x1, y - 8, y + 3)) return;
      placed.push({ x0: x0, x1: x1, y0: y - 8, y1: y + 3 });
      g.appendChild(el('text', { x: x, y: y, 'text-anchor': anchor, class: 'tick-text' }, label));
    }
    var xLabelY = xVisible ? xAxisY + 15 : padT + ih + 15;
    xTicks.forEach(function (tx) {
      if (Math.abs(tx) < 1e-9) return;
      addLabel(fmt(tx, 1), sx(tx), xLabelY, 'middle');
    });
    yTicks.forEach(function (ty) {
      if (Math.abs(ty) < 1e-9) return;
      addLabel(fmt(ty, 1), padL - 7, sy(ty) + 4, 'end');
    });
    if (xVisible && yVisible) {
      // one shared 0 at the origin
      g.appendChild(el('text', { x: yAxisX - 6, y: xAxisY + 14, 'text-anchor': 'end', class: 'tick-text' }, '0'));
    }

    var hx = -b / (2 * a), ky = c - b * b / (4 * a);
    // symmetry axis + vertex
    if (hx >= win.xmin && hx <= win.xmax) {
      svg.appendChild(el('path', { d: 'M' + sx(hx) + ',' + padT + ' V' + (padT + ih), class: 'sym-line', 'clip-path': 'url(#quad-demo-clip)' }));
    }
    // curve: sampled per ~2 device pixels, clipped rather than dropped
    var d = '', n = Math.min(600, Math.max(160, Math.round(iw * 2)));
    for (i = 0; i <= n; i += 1) {
      var xx = win.xmin + (win.xmax - win.xmin) * (i / n);
      var px = sx(xx), py = sy(a * xx * xx + b * xx + c);
      d += (i === 0 ? 'M' : 'L') + px.toFixed(2) + ',' + py.toFixed(2);
    }
    var area = d + 'L' + sx(win.xmax).toFixed(2) + ',' + (padT + ih) + 'L' + sx(win.xmin).toFixed(2) + ',' + (padT + ih) + 'Z';
    var fill = el('path', { d: area, fill: 'url(#quad-demo-grad)', 'clip-path': 'url(#quad-demo-clip)' });
    var curve = el('path', { d: d, class: 'curve', 'clip-path': 'url(#quad-demo-clip)' });
    svg.appendChild(fill);
    svg.appendChild(curve);

    // vertex label, flipped inside the plot when it would overflow
    var vx = sx(hx), vy = sy(ky);
    if (Math.abs(a) > 1e-6 && hx >= win.xmin && hx <= win.xmax && ky >= win.ymin && ky <= win.ymax) {
      svg.appendChild(el('circle', { cx: vx, cy: vy, r: 4, class: 'vertex-dot' }));
      var label = '顶点 (' + fmt(hx, 1) + ', ' + fmt(ky, 1) + ')';
      var lx = vx + 9, ly = vy - 9, anchor = 'start';
      if (lx + widthOf(label) > padL + iw - 4) { lx = vx - 9; ly = vy - 9; anchor = 'end'; }
      if (ly < padT + 12) { ly = vy + 16; }
      svg.appendChild(el('text', { x: lx, y: ly, 'text-anchor': anchor, class: 'vertex-label' }, label));
    }
    // real roots inside the window
    if (Math.abs(a) > 1e-6) {
      var disc = b * b - 4 * a * c;
      if (disc >= -1e-9) {
        var sq = Math.sqrt(Math.max(0, disc));
        var r1 = (-b - sq) / (2 * a), r2 = (-b + sq) / (2 * a);
        var roots = Math.abs(r1 - r2) < 1e-6 ? [r1] : [r1, r2];
        roots.forEach(function (rx) {
          if (rx < win.xmin || rx > win.xmax) return;
          svg.appendChild(el('circle', { cx: sx(rx), cy: sy(0), r: 3.5, class: 'root-dot' }));
          var ry = (xVisible ? xAxisY + 15 : padT + ih + 15) + 13;
          svg.appendChild(el('text', { x: sx(rx), y: ry, 'text-anchor': 'middle', class: 'root-label' }, 'x = ' + fmt(rx, 2)));
        });
      }
    }

    if (animate && !reduced) {
      try {
        var len = curve.getTotalLength();
        curve.style.strokeDasharray = String(len);
        curve.style.strokeDashoffset = String(len);
        curve.getBoundingClientRect();
        curve.style.transition = 'stroke-dashoffset 600ms ease-out';
        curve.style.strokeDashoffset = '0';
        curve.addEventListener('transitionend', function () {
          curve.style.strokeDasharray = ''; curve.style.strokeDashoffset = '';
        }, { once: true });
      } catch (e) { /* measurement unavailable: plain curve */ }
    }
    last = { a: a, b: b, c: c, win: win };
  }

  // --- readouts -----------------------------------------------------------
  function render(raw) {
    var a = round(readNum(raw.a, 1), 1), b = round(readNum(raw.b, 0), 1), c = round(readNum(raw.c, 0), 1);
    out('equation').textContent = equation(a, b, c);
    var up = a > 0;
    var isQuad = Math.abs(a) > 1e-6;

    if (!isQuad) {
      out('shape').textContent = '退化：一次函数';
      out('axis').textContent = Math.abs(b) > 1e-6 ? '对称轴 无' : '常数函数';
      out('vertex').textContent = '—';
      out('roots').textContent = Math.abs(b) > 1e-6 ? 'x = ' + fmt(-c / b, 2) : (Math.abs(c) < 1e-9 ? '全体实数' : '无');
      out('disc').textContent = fmt(b * b - 4 * a * c, 1);
      out('yint').textContent = '(0, ' + fmt(c, 1) + ')';
    } else {
      var disc = b * b - 4 * a * c;
      var hx = -b / (2 * a), ky = c - b * b / (4 * a);
      out('shape').textContent = up ? '开口向上 · 有最小值' : '开口向下 · 有最大值';
      out('axis').textContent = '对称轴 x = ' + fmt(hx, 2);
      out('vertex').textContent = '(' + fmt(hx, 1) + ', ' + fmt(ky, 1) + ')';
      if (disc > 1e-9) {
        var sq = Math.sqrt(disc);
        out('roots').textContent = '(' + fmt((-b - sq) / (2 * a), 2) + ', 0) · (' + fmt((-b + sq) / (2 * a), 2) + ', 0)';
      } else if (Math.abs(disc) <= 1e-9) {
        out('roots').textContent = '(' + fmt(-b / (2 * a), 2) + ', 0)（重根）';
      } else {
        out('roots').textContent = '无实数根';
      }
      out('disc').textContent = fmt(disc, 1);
      out('yint').textContent = '(0, ' + fmt(c, 1) + ')';
    }

    draw({ a: a, b: b, c: c }, !entered);
    entered = true;
    return {
      equation: equation(a, b, c),
      a: 'a = ' + fmt(a, 1),
      b: 'b = ' + fmt(b, 1),
      c: 'c = ' + fmt(c, 1),
    };
  }

  dshViz.bind('#quad-demo', render);

  // reset: defaults + fresh window (no entrance replay)
  root.querySelector('#quad-demo-reset').addEventListener('click', function () {
    var defs = { a: 1, b: 0, c: 0 };
    if (dshViz.state && dshViz.state.clear) dshViz.state.clear();
    root.querySelector('#quad-demo-a').value = String(defs.a);
    root.querySelector('#quad-demo-b').value = String(defs.b);
    root.querySelector('#quad-demo-c').value = String(defs.c);
    last = null;
    render(defs);
  });

  // re-layout when the card width changes; never replays the entrance
  if (typeof ResizeObserver === 'function') {
    var ro = new ResizeObserver(function () {
      if (!last) return;
      var w = Math.round(plot.clientWidth || 0), h = Math.round(plot.clientHeight || 0);
      if (!w || !h || (w === lastW && h === lastH)) return;
      draw({ a: last.a, b: last.b, c: last.c }, false);
    });
    ro.observe(plot);
  }
})();
</script>"}

